17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.server.ResponseStatusException;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        String normalizedAddress = normalizeAddress(owner.getAddress());
108	        if (normalizedAddress.isEmpty()) {
109	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
110	                "Address must not be blank after normalization");
111	        }
112	        owner.setAddress(normalizedAddress);
113	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
114	        owner.setTelephone(normalizedTelephone);
115	        owner.setEmail(normalizeEmail(owner.getEmail()));
116	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
117	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
118	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
119	        owner.setRegistrationDate(businessDate);
120	        long createdToday = this.clinicService.findAllOwners().stream()
121	            .map(Owner::getRegistrationDate)
122	            .filter(businessDate::equals)
123	            .count();
124	        if (createdToday >= 100) {
125	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
126	                "The maximum number of owners for today has already been reached");
127	        }
128	        owner.setBulkSignupWarning(createdToday > 80);
129	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
130	            .map(Owner::getTelephone)
131	            .filter(java.util.Objects::nonNull)
132	            .anyMatch(normalizedTelephone::equals);
133	        if (telephoneInUse) {
134	            throw new ResponseStatusException(HttpStatus.CONFLICT,
135	                "An owner with this telephone number already exists");
136	        }
137	        String lastNameKey = normalizeForHousehold(owner.getLastName());
138	        String addressKey = normalizeForHousehold(owner.getAddress());
139	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
140	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(lastNameKey)
141	                && normalizeForHousehold(existing.getAddress()).equals(addressKey))
142	            .toList();
143	        if (!householdMembers.isEmpty()) {
144	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
145	                throw new ResponseStatusException(HttpStatus.CONFLICT,
146	                    "An owner with this last name already exists at this address");
147	            }
148	            String householdId = householdId(lastNameKey, addressKey);
149	            owner.setHouseholdId(householdId);
150	            for (Owner member : householdMembers) {
151	                if (!householdId.equals(member.getHouseholdId())) {
152	                    member.setHouseholdId(householdId);
153	                    this.clinicService.saveOwner(member);
154	                }
155	            }
156	        }
157	        String cityKey = normalizeForHousehold(owner.getCity());
158	        long cityCount = this.clinicService.findAllOwners().stream()
159	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
160	            .count();
161	        if (cityCount >= 50) {
162	            throw new ResponseStatusException(HttpStatus.CONFLICT,
163	                "This city already has the maximum number of owners");
164	        }
165	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
166	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
167	        this.clinicService.saveOwner(owner);
168	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
169	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
170	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
171	        headers.setLocation(UriComponentsBuilder.newInstance()
172	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
173	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
174	    }
175	
176	    /**
177	     * Rolls a registration date forward to a business day. When {@code date} falls on a Saturday or
178	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
179	     * to the effective registration date (whether supplied in the request or defaulted to the server
180	     * date) so that every stored {@code registrationDate}, and any value derived from it, lands on a
181	     * business day.
182	     *
183	     * @param date the effective registration date
184	     * @return the same date if it is a weekday, otherwise the following Monday
185	     */
186	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
187	        return switch (date.getDayOfWeek()) {
188	            case SATURDAY -> date.plusDays(2);
189	            case SUNDAY -> date.plusDays(1);
190	            default -> date;
191	        };
192	    }
193	
194	    /**
195	     * Counts the owners that already exist (before the current create) whose first and last names
196	     * both match the supplied names, compared case-insensitively. The returned value is captured on
197	     * the new owner at creation time and does not change as further owners are added later.
198	     *
199	     * @param firstName the new owner's first name
200	     * @param lastName  the new owner's last name
201	     * @return the number of pre-existing namesake owners
202	     */
203	    private int namesakeCount(String firstName, String lastName) {
204	        return (int) this.clinicService.findAllOwners().stream()
205	            .filter(existing -> existing.getFirstName() != null
206	                && existing.getFirstName().equalsIgnoreCase(firstName)
207	                && existing.getLastName() != null
208	                && existing.getLastName().equalsIgnoreCase(lastName))
209	            .count();
210	    }
211	
212	    /**
213	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where
214	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} is the
215	     * upper-cased first three letters of the last name, and {@code NNNN} is a per-city 4-digit
216	     * zero-padded sequence equal to one more than the number of owners already in that city
217	     * (e.g. {@code 'SYD-SMI-0007'}).
218	     *
219	     * @param city     the owner's city
220	     * @param lastName the owner's last name
221	     * @return the assigned customer code
222	     */
223	    private String nextCustomerCode(String city, String lastName) {
224	        String cityPrefix = first3Upper(city);
225	        String lastPrefix = first3Upper(lastName);
226	        String cityKey = normalizeForHousehold(city);
227	        long sequence = this.clinicService.findAllOwners().stream()
228	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
229	            .count() + 1L;
230	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
231	    }
232	
233	    /**
234	     * Returns the upper-cased first three characters of {@code value}, or fewer if the value is
235	     * shorter. A {@code null} value yields the empty string.
236	     *
237	     * @param value the source value
238	     * @return the upper-cased first three characters
239	     */
240	    private String first3Upper(String value) {
241	        String v = (value == null ? "" : value);
242	        return v.substring(0, Math.min(3, v.length())).toUpperCase(java.util.Locale.ROOT);
243	    }
244	
245	    /**
246	     * Normalizes a street address applied whenever an owner is created: leading and trailing
247	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
248	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
249	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
250	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
251	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
252	     * {@code '12 MAIN STREET'}.
253	     *
254	     * @param address the raw address as submitted, or {@code null} when absent
255	     * @return the normalized address, or the empty string when the value is blank
256	     */
257	    private String normalizeAddress(String address) {
258	        String collapsed = (address == null ? "" : address)
259	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
260	        if (collapsed.isEmpty()) {
261	            return "";
262	        }
263	        String[] tokens = collapsed.split(" ");
264	        for (int i = 0; i < tokens.length; i++) {
265	            switch (tokens[i]) {
266	                case "ST" -> tokens[i] = "STREET";
267	                case "RD" -> tokens[i] = "ROAD";
268	                case "AVE" -> tokens[i] = "AVENUE";
269	                default -> { }
270	            }
271	        }
272	        return String.join(" ", tokens);
273	    }
274	
275	    /**
276	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
277	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
278	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
279	     * empty string.
280	     *
281	     * @param value the raw value (last name or address) as submitted
282	     * @return the normalized comparison key
283	     */
284	    private String normalizeForHousehold(String value) {
285	        if (value == null) {
286	            return "";
287	        }
288	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
289	    }
290	
291	    /**
292	     * Derives the stable shared household identifier for a household, keyed on the normalized last
293	     * name and address. Because it is a pure function of those normalized keys, every owner in the
294	     * same household deterministically computes the same value. The identifier is the first 12
295	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
296	     * (the separator prevents distinct name/address pairs from colliding).
297	     *
298	     * @param lastNameKey the normalized last-name comparison key
299	     * @param addressKey  the normalized address comparison key
300	     * @return the stable household identifier
301	     */
302	    private String householdId(String lastNameKey, String addressKey) {
303	        String seed = lastNameKey + "�" + addressKey;
304	        try {
305	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
306	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
307	            StringBuilder sb = new StringBuilder(digest.length * 2);
308	            for (byte b : digest) {
309	                sb.append(String.format("%02x", b));
310	            }
311	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
312	        }
313	        catch (java.security.NoSuchAlgorithmException e) {
314	            throw new IllegalStateException("SHA-256 not available", e);
315	        }
316	    }
317	
318	    /**
319	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
320	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
321	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
322	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
323	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
324	     * is stored as {@code '+61412345678'}.
325	     *
326	     * @param telephone the raw telephone number as submitted
327	     * @return the normalized E.164 telephone number
328	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
329	     *         number (8 to 15 digits after the '+')
330	     */
331	    private String normalizeTelephone(String telephone) {
332	        String raw = telephone == null ? "" : telephone.trim();
333	        String digits = raw.replaceAll("\\D", "");
334	        String e164;
335	        if (raw.startsWith("+")) {
336	            e164 = "+" + digits;
337	        } else {
338	            if (digits.startsWith("0")) {
339	                digits = digits.substring(1);
340	            }
341	            e164 = "+61" + digits;
342	        }
343	        int digitCount = e164.length() - 1;
344	        if (digitCount < 8 || digitCount > 15) {
345	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
346	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
347	        }
348	        return e164;
349	    }
350	
351	    /**
352	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
353	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
354	     * (absent) or already valid.
355	     *
356	     * @param email the email address as submitted, or {@code null} when absent
357	     * @return the lower-cased email, or {@code null} when absent
358	     */
359	    private String normalizeEmail(String email) {
360	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
361	    }
362	
363	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
364	    @Override
365	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
366	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
367	        if (currentOwner == null) {
368	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
369	        }
370	        currentOwner.setAddress(ownerFieldsDto.getAddress());
371	        currentOwner.setCity(ownerFieldsDto.getCity());
372	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
373	        currentOwner.setLastName(ownerFieldsDto.getLastName());
374	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
375	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
376	        this.clinicService.saveOwner(currentOwner);
377	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
378	    }
379	
380	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
381	    @Transactional
382	    @Override
383	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
384	        Owner owner = this.clinicService.findOwnerById(ownerId);
385	        if (owner == null) {
386	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
387	        }
388	        this.clinicService.deleteOwner(owner);
389	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
390	    }
391	
392	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
393	    @Override
394	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
395	        Owner owner = this.clinicService.findOwnerById(ownerId);
396	        if (owner == null) {
397	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
398	        }
399	        HttpHeaders headers = new HttpHeaders();
400	        Pet pet = petMapper.toPet(petFieldsDto);
401	        owner.setId(ownerId);
402	        pet.setOwner(owner);
403	        pet.getType().setName(null);
404	        this.clinicService.savePet(pet);
405	        PetDto petDto = petMapper.toPetDto(pet);
406	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
407	            .buildAndExpand(pet.getId()).toUri());
408	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
409	    }
410	
411	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
412	    @Override
413	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
414	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
415	        if (currentOwner != null) {
416	            Pet currentPet = this.clinicService.findPetById(petId);
417	            if (currentPet != null) {
418	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
419	                currentPet.setName(petFieldsDto.getName());
420	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
421	                this.clinicService.savePet(currentPet);
422	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
423	            }
424	        }
425	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
426	    }
427	
428	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
429	    @Override
430	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
431	        HttpHeaders headers = new HttpHeaders();
432	        Visit visit = visitMapper.toVisit(visitFieldsDto);
433	        Pet pet = new Pet();
434	        pet.setId(petId);
435	        visit.setPet(pet);
436	        this.clinicService.saveVisit(visit);
437	        VisitDto visitDto = visitMapper.toVisitDto(visit);
438	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
439	            .buildAndExpand(visit.getId()).toUri());
440	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
441	    }
442	
443	
444	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
445	    @Override
446	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
447	        Owner owner = this.clinicService.findOwnerById(ownerId);
448	        if (owner != null) {
449	            Pet pet = owner.getPet(petId);
450	            if (pet != null) {
451	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
452	            }
453	        }
454	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
455	    }
456	}
